package com.autoops.workflow.controller;import com.autoops.workflow.dto.WorkflowDraftDtos;import com.autoops.workflow.entity.Workflow;import com.autoops.workflow.service.WorkflowDraftService;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/workflows")public class WorkflowDraftController{private final WorkflowDraftService service;public WorkflowDraftController(WorkflowDraftService s){service=s;}@PostMapping("/draft")public Workflow save(@RequestBody WorkflowDraftDtos.Save d){return service.save(d);}}
